import { defineConfig } from "@hey-api/openapi-ts";

// `pnpm generate` writes openapi.json from the backend, then this generates src/api from it
export default defineConfig({
  input: "openapi.json",
  output: {
    path: "src/api",
    header: [
      "// Generated by `pnpm generate` from the backend's OpenAPI description. Don't edit it.",
      // Generated code isn't written for our strict TypeScript settings. Its types still check the code that calls it.
      "// @ts-nocheck",
    ],
  },
  plugins: [
    // The API is on the frontend's domain under /api, so requests use relative URLs
    { name: "@hey-api/client-fetch", baseUrl: false },
    "@tanstack/react-query",
  ],
});
